import{_ as r,o as t,c as a,a3 as o}from"./chunks/framework.DBpCFmh2.js";const u=JSON.parse('{"title":"消息流与工具调用","description":"本文面向\\"从用户输入到 LLM 响应\\"的完整消息流转，重点解释 Chrome 扩展端（Manifest V3 Service Worker）与独立本地 Agent 服务之间的 HTTP/WebSocket 通信契约、ReAct 推理循环中的思考-行动-观察序列、工具参数校验与结果聚合、工具预筛选算法、并行执行优化、超时控制、消息去重、重试策略与性能监控指标。","frontmatter":{"title":"消息流与工具调用","description":"本文面向\\"从用户输入到 LLM 响应\\"的完整消息流转，重点解释 Chrome 扩展端（Manifest V3 Service Worker）与独立本地 Agent 服务之间的 HTTP/WebSocket 通信契约、ReAct 推理循环中的思考-行动-观察序列、工具参数校验与结果聚合、工具预筛选算法、并行执行优化、超时控制、消息去重、重试策略与性能监控指标。"},"headers":[],"relativePath":"系统架构设计/数据流设计/消息流与工具调用/index.md","filePath":"系统架构设计/数据流设计/消息流与工具调用/index.md","lastUpdated":null}'),l={name:"系统架构设计/数据流设计/消息流与工具调用/index.md"};function n(i,e,c,s,g,h){return t(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="消息流与工具调用" tabindex="-1">消息流与工具调用 <a class="header-anchor" href="#消息流与工具调用" aria-label="Permalink to &quot;消息流与工具调用&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js" target="_blank" rel="noreferrer">src/background/index.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js" target="_blank" rel="noreferrer">src/background/local-agent-client.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js" target="_blank" rel="noreferrer">src/background/tool-executor.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-preselector.js" target="_blank" rel="noreferrer">src/background/tool-preselector.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js" target="_blank" rel="noreferrer">src/background/react-loop.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js" target="_blank" rel="noreferrer">src/background/stream-controller.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js" target="_blank" rel="noreferrer">agent/src/server.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js" target="_blank" rel="noreferrer">agent/src/executor.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/shared/tools.js" target="_blank" rel="noreferrer">src/shared/tools.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/constants.js" target="_blank" rel="noreferrer">src/background/constants.js</a></li></ul></details><h2 id="更新摘要" tabindex="-1">更新摘要 <a class="header-anchor" href="#更新摘要" aria-label="Permalink to &quot;更新摘要&quot;">​</a></h2><p><strong>变更内容</strong></p><ul><li>增强了工具预筛选器的 JSON 信封恢复机制，新增 <code>recoverAnswerEnvelopeData</code> 和 <code>looksLikePreselectEnvelope</code> 函数</li><li>改进了对 AI 模型响应不一致的容错处理能力</li><li>更新了工具预筛选算法以支持新的 JSON 格式并增强向后兼容性</li><li>完善了错误处理和降级策略</li></ul><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构">项目结构</a></li><li><a href="#核心组件">核心组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#详细组件分析">详细组件分析</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能与并发优化">性能与并发优化</a></li><li><a href="#故障排查指南">故障排查指南</a></li><li><a href="#结论">结论</a></li><li><a href="#附录协议与状态定义">附录：协议与状态定义</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本文面向&quot;从用户输入到 LLM 响应&quot;的完整消息流转，重点解释 Chrome 扩展端（Manifest V3 Service Worker）与独立本地 Agent 服务之间的 HTTP/WebSocket 通信契约、ReAct 推理循环中的思考-行动-观察序列、工具参数校验与结果聚合、工具预筛选算法、并行执行优化、超时控制、消息去重、重试策略与性能监控指标。文档同时给出时序图、工具调用状态图和错误传播路径，帮助读者在理解整体架构的同时定位具体实现位置。</p><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><p>本项目采用双进程架构：</p><ul><li>Chrome 扩展端（src/）：Service Worker 入口 background/index.js，负责 ReAct 循环、工具调度、侧边栏 UI 状态、保活与自动续跑。</li><li>本地 Agent 端（agent/src/）：Node.js 服务 agent/src/server.js，提供文件系统、命令执行、MCP 工具注册、RAG 等能力，并通过 WebSocket 推送命令输出。</li></ul><pre class="mermaid">graph TB
subgraph &quot;Chrome 扩展端&quot;
SW[&quot;Service Worker&lt;br/&gt;background/index.js&quot;]
RL[&quot;ReAct 循环&lt;br/&gt;background/react-loop.js&quot;]
TE[&quot;工具执行器&lt;br/&gt;background/tool-executor.js&quot;]
PS[&quot;工具预筛选&lt;br/&gt;background/tool-preselector.js&quot;]
SC[&quot;流式控制器&lt;br/&gt;background/stream-controller.js&quot;]
AC[&quot;Agent 客户端&lt;br/&gt;background/local-agent-client.js&quot;]
SP[&quot;侧边栏 UI&lt;br/&gt;side_panel/chat-manager.js / chat-streaming.js&quot;]
end
subgraph &quot;本地 Agent 端&quot;
AGS[&quot;HTTP + WebSocket 服务器&lt;br/&gt;agent/src/server.js&quot;]
EXE[&quot;命令执行器&lt;br/&gt;agent/src/executor.js&quot;]
end
SP --&gt; SW
SW --&gt; RL
RL --&gt; PS
RL --&gt; TE
TE --&gt; AC
AC --&gt; AGS
AGS --&gt; EXE
RL --&gt; SC
SC --&gt; SP
</pre><p><strong>图示来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L1-L120" target="_blank" rel="noreferrer">src/background/index.js#L1-L120</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L728-L760" target="_blank" rel="noreferrer">src/background/react-loop.js#L728-L760</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L547-L651" target="_blank" rel="noreferrer">src/background/tool-executor.js#L547-L651</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-preselector.js#L273-L432" target="_blank" rel="noreferrer">src/background/tool-preselector.js#L273-L432</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L36-L280" target="_blank" rel="noreferrer">src/background/stream-controller.js#L36-L280</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L399-L443" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L399-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L425" target="_blank" rel="noreferrer">agent/src/server.js#L388-L425</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L1-L120" target="_blank" rel="noreferrer">src/background/index.js#L1-L120</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/constants.js#L1-L26" target="_blank" rel="noreferrer">src/background/constants.js#L1-L26</a></li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><ul><li>ReAct 推理循环：background/react-loop.js 维护多轮迭代、流式解析、工具调用、循环检测、子任务计划与恢复。</li><li>工具执行器：background/tool-executor.js 统一工具定义、动态 MCP/RAG 工具注入、并行执行、确认门控、审计日志。</li><li>工具预筛选：background/tool-preselector.js 通过轻量模型调用判断是否需要工具及选择哪些工具，减少上下文压力，<strong>新增 JSON 信封恢复机制</strong>。</li><li>Agent 客户端：background/local-agent-client.js 封装 HTTP/WebSocket 认证、请求超时、可达性缓存、MCP/RAG API。</li><li>流式控制器：background/stream-controller.js 解析 SSE、节流发送、tool_calls 累积、usage 提取、空闲超时保护。</li><li>侧边栏 UI：side_panel/chat-manager.js 与 chat-streaming.js 负责消息渲染、流式更新、工具卡片、执行日志面板。</li><li>Agent 服务端：agent/src/server.js 提供 REST 路由、CORS、认证、文件上传、命令执行、MCP/RAG 集成。</li><li>命令执行器：agent/src/executor.js 管理子进程、流式 stdout/stderr、超时策略、进程组终止。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L728-L800" target="_blank" rel="noreferrer">src/background/react-loop.js#L728-L800</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L448-L651" target="_blank" rel="noreferrer">src/background/tool-executor.js#L448-L651</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-preselector.js#L273-L432" target="_blank" rel="noreferrer">src/background/tool-preselector.js#L273-L432</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L399-L443" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L399-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L36-L280" target="_blank" rel="noreferrer">src/background/stream-controller.js#L36-L280</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js#L54-L83" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js#L54-L83</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L677-L726" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L677-L726</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L425" target="_blank" rel="noreferrer">agent/src/server.js#L388-L425</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>下图展示一次典型请求从侧边栏发起，经过 Service Worker、ReAct 循环、工具执行、Agent 服务、命令执行，再返回流式响应的完整链路。</p><pre class="mermaid">sequenceDiagram
participant UI as &quot;侧边栏 UI&lt;br/&gt;chat-manager.js / chat-streaming.js&quot;
participant SW as &quot;Service Worker&lt;br/&gt;index.js&quot;
participant RL as &quot;ReAct 循环&lt;br/&gt;react-loop.js&quot;
participant PS as &quot;工具预筛选&lt;br/&gt;tool-preselector.js&quot;
participant TE as &quot;工具执行器&lt;br/&gt;tool-executor.js&quot;
participant AC as &quot;Agent 客户端&lt;br/&gt;local-agent-client.js&quot;
participant AGS as &quot;Agent 服务器&lt;br/&gt;server.js&quot;
participant EXE as &quot;命令执行器&lt;br/&gt;executor.js&quot;
UI-&gt;&gt;SW : 发送 CALL_API / 启动 ReAct
SW-&gt;&gt;RL : reactLoop(messages, model, tools, ...)
RL-&gt;&gt;PS : preselectTools(可选)
PS--&gt;&gt;RL : 直接回答 或 选定工具集
RL-&gt;&gt;TE : executeTool(toolName, args)
TE-&gt;&gt;AC : agentRequest(&#39;/api/...&#39;) 或 createExecWebSocket()
AC-&gt;&gt;AGS : HTTP POST /api/fs|/api/exec|/api/mcp/call
AGS-&gt;&gt;EXE : spawn 子进程 / 流式输出
EXE--&gt;&gt;AGS : stdout/stderr/exit
AGS--&gt;&gt;AC : JSON 响应 或 WS 事件
AC--&gt;&gt;TE : {success, content/error}
TE--&gt;&gt;RL : 工具结果
RL-&gt;&gt;SC : StreamController.feedLine()
SC--&gt;&gt;UI : STREAM_START / STREAM_CHUNK / STREAM_TOOL_CALL / STREAM_DONE
</pre><p><strong>图示来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L728-L800" target="_blank" rel="noreferrer">src/background/react-loop.js#L728-L800</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-preselector.js#L273-L432" target="_blank" rel="noreferrer">src/background/tool-preselector.js#L273-L432</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L547-L651" target="_blank" rel="noreferrer">src/background/tool-executor.js#L547-L651</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L399-L443" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L399-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L425" target="_blank" rel="noreferrer">agent/src/server.js#L388-L425</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L36-L280" target="_blank" rel="noreferrer">src/background/stream-controller.js#L36-L280</a></li></ul><h2 id="详细组件分析" tabindex="-1">详细组件分析 <a class="header-anchor" href="#详细组件分析" aria-label="Permalink to &quot;详细组件分析&quot;">​</a></h2><h3 id="react-推理循环-思考-行动-观察" tabindex="-1">ReAct 推理循环：思考-行动-观察 <a class="header-anchor" href="#react-推理循环-思考-行动-观察" aria-label="Permalink to &quot;ReAct 推理循环：思考-行动-观察&quot;">​</a></h3><p>ReAct 循环是消息流的核心编排器：</p><ul><li>每轮先构建系统提示与历史，调用 LLM 获取内容增量或 tool_calls。</li><li>若检测到 tool_calls，立即通知前端显示工具卡片，随后按顺序或并行执行工具，将结果作为 observation 回注消息。</li><li>支持子任务 plan_task 拆分、循环检测、反思评估、checkpoint 持久化与自动续跑。</li></ul><pre class="mermaid">flowchart TD
Start([&quot;进入 reactLoopImpl&quot;]) --&gt; BuildCtx[&quot;构建消息上下文&lt;br/&gt;含历史/压缩/引用&quot;]
BuildCtx --&gt; CallLLM[&quot;调用 LLMSSE 流式&quot;]
CallLLM --&gt; HasTool{&quot;是否包含 tool_calls？&quot;}
HasTool --&gt; |否| EmitContent[&quot;输出文本/推理内容&quot;]
EmitContent --&gt; NextIter[&quot;下一轮迭代&quot;]
HasTool --&gt; |是| ExecTools[&quot;执行工具串行/并行&quot;]
ExecTools --&gt; Observe[&quot;收集工具结果并追加为 tool 消息&quot;]
Observe --&gt; NextIter
NextIter --&gt; LoopCheck{&quot;达到最大迭代/超时/循环检测？&quot;}
LoopCheck --&gt; |是| Finish([&quot;结束并保存 checkpoint/清理&quot;])
LoopCheck --&gt; |否| CallLLM
</pre><p><strong>图示来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L728-L800" target="_blank" rel="noreferrer">src/background/react-loop.js#L728-L800</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L287-L409" target="_blank" rel="noreferrer">src/background/stream-controller.js#L287-L409</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L728-L800" target="_blank" rel="noreferrer">src/background/react-loop.js#L728-L800</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L287-L409" target="_blank" rel="noreferrer">src/background/stream-controller.js#L287-L409</a></li></ul><h3 id="工具预筛选算法" tabindex="-1">工具预筛选算法 <a class="header-anchor" href="#工具预筛选算法" aria-label="Permalink to &quot;工具预筛选算法&quot;">​</a></h3><p>当工具数量超过固定阈值时，预筛选会调用轻量模型决定&quot;直接回答&quot;还是&quot;需要工具&quot;，并返回候选工具名列表；若无法解析或结果为空，则回退为全量工具。<strong>新增的 JSON 信封恢复机制显著提升了容错能力</strong>。</p><pre class="mermaid">flowchart TD
A[&quot;收到 messages/tools&quot;] --&gt; B{&quot;工具数 &gt; PRESELECT_MIN_TOOL_COUNT？&quot;}
B --&gt; |否| Skip[&quot;跳过预筛选，使用全部工具&quot;]
B --&gt; |是| Extract[&quot;提取最近用户问题与历史上下文&quot;]
Extract --&gt; Prompt[&quot;构建预筛选 prompt&quot;]
Prompt --&gt; ModelCall[&quot;调用模型response_format=json_object&quot;]
ModelCall --&gt; Parse[&quot;解析 JSON：answer 或 tools&quot;]
Parse --&gt; |answer| Direct[&quot;直接回答，不二次调用&quot;]
Parse --&gt; |tools| Match[&quot;按名称匹配工具集合&quot;]
Match --&gt; Fallback{&quot;匹配为空？&quot;}
Fallback --&gt; |是| AllTools[&quot;回退为全部工具&quot;]
Fallback --&gt; |否| Selected[&quot;返回筛选后的工具集&quot;]
</pre><p><strong>更新</strong> 新增了 JSON 信封恢复机制，包括 <code>recoverAnswerEnvelopeData</code> 和 <code>looksLikePreselectEnvelope</code> 函数，用于处理 AI 模型响应不一致的情况。</p><p><strong>图示来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-preselector.js#L273-L432" target="_blank" rel="noreferrer">src/background/tool-preselector.js#L273-L432</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/constants.js#L24-L26" target="_blank" rel="noreferrer">src/background/constants.js#L24-L26</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-preselector.js#L273-L432" target="_blank" rel="noreferrer">src/background/tool-preselector.js#L273-L432</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/constants.js#L24-L26" target="_blank" rel="noreferrer">src/background/constants.js#L24-L26</a></li></ul><h3 id="json-信封恢复机制" tabindex="-1">JSON 信封恢复机制 <a class="header-anchor" href="#json-信封恢复机制" aria-label="Permalink to &quot;JSON 信封恢复机制&quot;">​</a></h3><p><strong>新增功能</strong> 工具预筛选器现在具备强大的 JSON 信封恢复能力，能够处理 AI 模型响应中的格式错误：</p><pre class="mermaid">flowchart TD
RawText[&quot;原始模型响应&quot;] --&gt; TryParse[&quot;尝试 JSON.parse&quot;]
TryParse --&gt; |成功| ValidJSON[&quot;有效 JSON 对象&quot;]
TryParse --&gt; |失败| CheckEnvelope[&quot;检查是否为预筛选信封&quot;]
CheckEnvelope --&gt; |是| RecoverData[&quot;recoverAnswerEnvelopeData 恢复数据&quot;]
CheckEnvelope --&gt; |否| Fallback[&quot;回退到旧格式提取&quot;]
RecoverData --&gt; |成功| AnswerType[&quot;返回 answer 类型&quot;]
RecoverData --&gt; |失败| Malformed[&quot;标记为畸形信封&quot;]
ValidJSON --&gt; ProcessType[&quot;处理 type/data 字段&quot;]
ProcessType --&gt; AnswerOrTools[&quot;answer 或 tools 类型&quot;]
</pre><p><strong>新增的关键函数：</strong></p><ul><li><code>looksLikePreselectEnvelope(text)</code>：检测文本是否像 <code>{type,data}</code> 预筛选信封但 JSON.parse 已失败</li><li><code>recoverAnswerEnvelopeData(text)</code>：从格式错误的信封中提取 data 字符串内容，支持反转义常见序列</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-preselector.js#L155-L187" target="_blank" rel="noreferrer">src/background/tool-preselector.js#L155-L187</a></li></ul><h3 id="工具参数验证与结果聚合" tabindex="-1">工具参数验证与结果聚合 <a class="header-anchor" href="#工具参数验证与结果聚合" aria-label="Permalink to &quot;工具参数验证与结果聚合&quot;">​</a></h3><ul><li>参数解析：工具 handler 中通过 tryParseToolArgs 等辅助函数解析 arguments，兼容字符串与对象两种格式。</li><li>安全校验：网络访问受内网白名单限制；敏感操作需用户确认；命令执行走 Agent 端安全检查与安全环境变量白名单。</li><li>结果聚合：工具执行结果以 tool 消息追加到当前会话；执行日志节点记录成功/失败、耗时、stdout/stderr 摘要；子任务失败时生成部分产出摘要供父任务继续。</li></ul><pre class="mermaid">flowchart TD
Args[&quot;工具入参arguments&quot;] --&gt; Parse[&quot;解析与类型转换&quot;]
Parse --&gt; Validate[&quot;业务校验/安全门控&quot;]
Validate --&gt; |通过| Execute[&quot;执行工具浏览器/Agent/MCP/RAG&quot;]
Validate --&gt; |拒绝| Error[&quot;返回错误结果&quot;]
Execute --&gt; Result[&quot;标准化结果content/error&quot;]
Result --&gt; Log[&quot;写入执行日志节点&quot;]
Log --&gt; Append[&quot;追加为 tool 消息&quot;]
</pre><p><strong>图示来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L1-L23" target="_blank" rel="noreferrer">src/background/tool-executor.js#L1-L23</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L452-L541" target="_blank" rel="noreferrer">src/background/react-loop.js#L452-L541</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L118-L156" target="_blank" rel="noreferrer">agent/src/executor.js#L118-L156</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L1-L23" target="_blank" rel="noreferrer">src/background/tool-executor.js#L1-L23</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L452-L541" target="_blank" rel="noreferrer">src/background/react-loop.js#L452-L541</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L118-L156" target="_blank" rel="noreferrer">agent/src/executor.js#L118-L156</a></li></ul><h3 id="chrome-扩展端与-agent-服务的通信协议" tabindex="-1">Chrome 扩展端与 Agent 服务的通信协议 <a class="header-anchor" href="#chrome-扩展端与-agent-服务的通信协议" aria-label="Permalink to &quot;Chrome 扩展端与 Agent 服务的通信协议&quot;">​</a></h3><ul><li>HTTP 认证：所有需认证的请求携带 Authorization: Bearer &lt;token&gt;，Token 由配对流程获得并加密存储。</li><li>主要端点：/api/pair、/api/status、/api/fs/<em>、/api/exec、/api/mcp/</em>、/api/skill/<em>、/api/rag/</em>、/api/files/upload。</li><li>WebSocket：/api/exec 可建立 WS 连接，实时推送 stdout/stderr/exit；Token 通过查询参数传递。</li><li>CORS：仅允许 chrome-extension:// 来源跨域读取响应，防止恶意网页窃取无认证接口数据。</li></ul><pre class="mermaid">sequenceDiagram
participant AC as &quot;Agent 客户端&lt;br/&gt;local-agent-client.js&quot;
participant AGS as &quot;Agent 服务器&lt;br/&gt;server.js&quot;
AC-&gt;&gt;AGS : POST /api/pair {code, extensionId}
AGS--&gt;&gt;AC : {success, token}
AC-&gt;&gt;AGS : GET /api/status (无认证)
AGS--&gt;&gt;AC : {version, platform, ragAvailable}
AC-&gt;&gt;AGS : POST /api/fs/read/write/list/delete/search (Bearer Token)
AGS--&gt;&gt;AC : {success, content/error}
AC-&gt;&gt;AGS : POST /api/exec (Bearer Token)
AGS--&gt;&gt;AC : {execId}
AC-&gt;&gt;AGS : ws : //host : port?token=...
AGS--&gt;&gt;AC : {type : stdout|stderr|exit|error}
</pre><p><strong>图示来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L40-L94" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L40-L94</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L399-L443" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L399-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L662-L728" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L662-L728</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L471-L548" target="_blank" rel="noreferrer">agent/src/server.js#L471-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L751-L800" target="_blank" rel="noreferrer">agent/src/server.js#L751-L800</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L40-L94" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L40-L94</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L399-L443" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L399-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L662-L728" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L662-L728</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L471-L548" target="_blank" rel="noreferrer">agent/src/server.js#L471-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L751-L800" target="_blank" rel="noreferrer">agent/src/server.js#L751-L800</a></li></ul><h3 id="工具调用状态图" tabindex="-1">工具调用状态图 <a class="header-anchor" href="#工具调用状态图" aria-label="Permalink to &quot;工具调用状态图&quot;">​</a></h3><p>工具调用经历创建、等待确认（可选）、执行、流式输出、完成/失败、取消/超时等状态。</p><pre class="mermaid">stateDiagram-v2
[*] --&gt; 待执行
待执行 --&gt; 等待确认 : requiresConfirmation=true
等待确认 --&gt; 已确认 : 用户同意
等待确认 --&gt; 已拒绝 : 用户拒绝/超时/面板关闭
待执行 --&gt; 执行中 : 无需确认 或 已确认
执行中 --&gt; 流式输出 : stdout/stderr 开始
流式输出 --&gt; 已完成 : exitCode=0
流式输出 --&gt; 已失败 : exitCode!=0 或异常
执行中 --&gt; 已取消 : 用户停止/会话取消
执行中 --&gt; 已超时 : 代理端预算耗尽/扩展端保险上限
已确认 --&gt; 已取消
已拒绝 --&gt; [*]
已完成 --&gt; [*]
已失败 --&gt; [*]
已取消 --&gt; [*]
已超时 --&gt; [*]
</pre><p><strong>图示来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L438-L446" target="_blank" rel="noreferrer">src/background/tool-executor.js#L438-L446</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L285-L450" target="_blank" rel="noreferrer">src/background/react-loop.js#L285-L450</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L438-L446" target="_blank" rel="noreferrer">src/background/tool-executor.js#L438-L446</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L285-L450" target="_blank" rel="noreferrer">src/background/react-loop.js#L285-L450</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li></ul><h3 id="错误传播路径" tabindex="-1">错误传播路径 <a class="header-anchor" href="#错误传播路径" aria-label="Permalink to &quot;错误传播路径&quot;">​</a></h3><ul><li>扩展端 fetch 超时/网络错误：local-agent-client.js 返回 success=false 与本地化错误文案，并附加 httpStatus 区分 404 与离线。</li><li>Agent 端认证失败：server.js 返回 401/403，security 模块记录审计日志。</li><li>命令执行失败：executor.js 广播 error/exit，扩展端根据 exitCode/killed/timedOut 构造用户可见结果。</li><li>流式空闲超时：stream-controller.js 抛出 StreamIdleTimeout，react-loop.js 捕获后中断并提示重试。</li><li><strong>新增</strong> 工具预筛选 JSON 信封恢复失败：回退为全量工具，避免将畸形信封透传给 UI。</li></ul><pre class="mermaid">flowchart TD
NetErr[&quot;网络/超时错误&quot;] --&gt; ClientErr[&quot;local-agent-client 返回错误&quot;]
AuthFail[&quot;认证失败&quot;] --&gt; ServerErr[&quot;server.js 返回 401/403&quot;]
ExecErr[&quot;命令异常&quot;] --&gt; WSErr[&quot;WS 广播 error/exit&quot;]
IdleTO[&quot;流式空闲超时&quot;] --&gt; StreamErr[&quot;stream-controller 抛出异常&quot;]
MalformedJSON[&quot;预筛选 JSON 信封恢复失败&quot;] --&gt; Fallback[&quot;回退全量工具&quot;]
ClientErr --&gt; UI[&quot;侧边栏显示错误&quot;]
ServerErr --&gt; UI
WSErr --&gt; UI
StreamErr --&gt; UI
Fallback --&gt; UI
</pre><p><strong>图示来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L399-L443" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L399-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L537-L548" target="_blank" rel="noreferrer">agent/src/server.js#L537-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L326-L383" target="_blank" rel="noreferrer">agent/src/executor.js#L326-L383</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L391-L409" target="_blank" rel="noreferrer">src/background/stream-controller.js#L391-L409</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-preselector.js#L474-L477" target="_blank" rel="noreferrer">src/background/tool-preselector.js#L474-L477</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L399-L443" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L399-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L537-L548" target="_blank" rel="noreferrer">agent/src/server.js#L537-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L326-L383" target="_blank" rel="noreferrer">agent/src/executor.js#L326-L383</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L391-L409" target="_blank" rel="noreferrer">src/background/stream-controller.js#L391-L409</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><ul><li>background/index.js 作为 Service Worker 入口，协调 keepalive、自动续跑、侧边栏可见性、定时任务与 checkpoint 清理。</li><li>background/react-loop.js 依赖 tool-executor.js 获取工具与执行工具，依赖 stream-controller.js 解析 SSE，依赖 local-agent-client.js 进行 Agent 通信。</li><li>background/tool-executor.js 动态注入 MCP/RAG 工具，维护 PARALLELIZABLE_TOOLS 与 CONFIRMATION_REQUIRED_TOOLS。</li><li>background/tool-preselector.js 提供增强的 JSON 信封恢复能力，处理 AI 模型响应不一致的情况。</li><li>side_panel/chat-manager.js 与 chat-streaming.js 消费 STREAM_* 消息，渲染思考过程、工具卡片与执行日志。</li><li>agent/src/server.js 作为 HTTP+WebSocket 网关，分发到 executor.js、mcp registry、skill registry、memory routes、rag detect/install。</li></ul><pre class="mermaid">graph LR
Index[&quot;background/index.js&quot;] --&gt; ReactLoop[&quot;background/react-loop.js&quot;]
ReactLoop --&gt; ToolExec[&quot;background/tool-executor.js&quot;]
ReactLoop --&gt; StreamCtrl[&quot;background/stream-controller.js&quot;]
ToolExec --&gt; LocalAgent[&quot;background/local-agent-client.js&quot;]
LocalAgent --&gt; AgentServer[&quot;agent/src/server.js&quot;]
AgentServer --&gt; Executor[&quot;agent/src/executor.js&quot;]
ToolPreselector[&quot;background/tool-preselector.js&quot;] --&gt; Index
ChatMgr[&quot;side_panel/chat-manager.js&quot;] --&gt; ChatStream[&quot;side_panel/chat-streaming.js&quot;]
ChatStream --&gt; ReactLoop
</pre><p><strong>图示来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L1-L120" target="_blank" rel="noreferrer">src/background/index.js#L1-L120</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L728-L800" target="_blank" rel="noreferrer">src/background/react-loop.js#L728-L800</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L547-L651" target="_blank" rel="noreferrer">src/background/tool-executor.js#L547-L651</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L399-L443" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L399-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L425" target="_blank" rel="noreferrer">agent/src/server.js#L388-L425</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js#L54-L83" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js#L54-L83</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L677-L726" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L677-L726</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L1-L120" target="_blank" rel="noreferrer">src/background/index.js#L1-L120</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/react-loop.js#L728-L800" target="_blank" rel="noreferrer">src/background/react-loop.js#L728-L800</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L547-L651" target="_blank" rel="noreferrer">src/background/tool-executor.js#L547-L651</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L399-L443" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L399-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L425" target="_blank" rel="noreferrer">agent/src/server.js#L388-L425</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-manager.js#L54-L83" target="_blank" rel="noreferrer">src/side_panel/chat-manager.js#L54-L83</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/chat-streaming.js#L677-L726" target="_blank" rel="noreferrer">src/side_panel/chat-streaming.js#L677-L726</a></li></ul><h2 id="性能与并发优化" tabindex="-1">性能与并发优化 <a class="header-anchor" href="#性能与并发优化" aria-label="Permalink to &quot;性能与并发优化&quot;">​</a></h2><ul><li>工具预筛选：当工具数量超过 PRESELECT_MIN_TOOL_COUNT（默认 10）时触发，减少 LLM 上下文压力与无效工具调用。</li><li>并行执行：PARALLELIZABLE_TOOLS 标记的工具可并行执行，提升吞吐；CONFIRMATION_REQUIRED_TOOLS 强制串行确认。</li><li>流式节流：StreamController 的 streamChunkDelay 控制字符级渲染频率，避免 UI 抖动。</li><li>空闲超时：STREAM_IDLE_TIMEOUT_MS 防止流式数据卡住；Agent 命令执行采用&quot;有输出才延长&quot;的策略，静默即杀。</li><li>消息去重：tool_call.id 唯一键与 inFlightConfirmKeys 防止重复确认；completedProcesses 缓存回放避免重复输出。</li><li>重试策略：fetchWithRetry 支持指数退避；preselectTools 与 react-loop 对 API 失败进行降级处理。</li><li><strong>新增</strong> JSON 信封恢复：显著提升对 AI 模型响应不一致的容错能力，减少因格式错误导致的失败率。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/constants.js#L24-L26" target="_blank" rel="noreferrer">src/background/constants.js#L24-L26</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/constants.js#L132-L149" target="_blank" rel="noreferrer">src/background/constants.js#L132-L149</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L36-L280" target="_blank" rel="noreferrer">src/background/stream-controller.js#L36-L280</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L165-L186" target="_blank" rel="noreferrer">agent/src/executor.js#L165-L186</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-preselector.js#L273-L432" target="_blank" rel="noreferrer">src/background/tool-preselector.js#L273-L432</a></li></ul><h2 id="故障排查指南" tabindex="-1">故障排查指南 <a class="header-anchor" href="#故障排查指南" aria-label="Permalink to &quot;故障排查指南&quot;">​</a></h2><ul><li>Service Worker 生命周期：keepalive port 用于保活；SW 重启后通过 SW_RESTARTED 通知侧边栏，支持从 checkpoint 恢复。</li><li>配对与连通性：pair 失败、代理未配对、代理服务未连接等错误由 local-agent-client.js 本地化提示；可达性缓存避免频繁探测。</li><li>命令执行超时：executor.js 的 decideTimeoutAction 基于输出心跳延长预算；扩展端 toolTimeout 为保险上限。</li><li>流式卡顿：STREAM_IDLE_TIMEOUT_MS 触发空闲超时；检查网络与服务提供商稳定性。</li><li>侧边栏不可见：isPanelVisibleToUser 与焦点镜像确保通知可见性；快捷键 toggle 需手势上下文。</li><li><strong>新增</strong> 工具预筛选 JSON 信封错误：检查 AI 模型响应格式，查看 recoverAnswerEnvelopeData 是否能成功恢复数据。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L140-L218" target="_blank" rel="noreferrer">src/background/index.js#L140-L218</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L275-L330" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L275-L330</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L165-L186" target="_blank" rel="noreferrer">agent/src/executor.js#L165-L186</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/stream-controller.js#L287-L409" target="_blank" rel="noreferrer">src/background/stream-controller.js#L287-L409</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>本方案通过 ReAct 循环编排思考-行动-观察序列，结合工具预筛选、并行执行、流式输出与严格的超时控制，实现了从用户输入到 LLM 响应的稳定、可观测、可扩展的消息流。<strong>新增的 JSON 信封恢复机制显著提升了系统的鲁棒性</strong>，能够有效处理 AI 模型响应不一致的问题。Chrome 扩展端与 Agent 服务之间通过带认证的 HTTP/WebSocket 协议交互，支持文件、命令、MCP 工具与 RAG 能力。错误传播路径清晰，具备自动续跑、消息去重与重试机制，适合复杂自动化场景。</p><h2 id="附录-协议与状态定义" tabindex="-1">附录：协议与状态定义 <a class="header-anchor" href="#附录-协议与状态定义" aria-label="Permalink to &quot;附录：协议与状态定义&quot;">​</a></h2><ul><li>HTTP 端点：/api/pair、/api/status、/api/fs/<em>、/api/exec、/api/mcp/</em>、/api/skill/<em>、/api/rag/</em>、/api/files/upload。</li><li>WebSocket：/api/exec 建立连接，推送 stdout/stderr/exit/error。</li><li>认证：Authorization: Bearer &lt;token&gt;；配对码一次性认证。</li><li>工具状态：待执行 → 等待确认 → 执行中 → 流式输出 → 已完成/已失败/已取消/已超时。</li><li><strong>新增</strong> 预筛选响应格式：支持 <code>{type: &quot;answer&quot;, data: &quot;...&quot;}</code> 和 <code>{type: &quot;tools&quot;, data: [...]}</code> 新格式，以及向后兼容的旧格式。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L40-L94" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L40-L94</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L399-L443" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L399-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L662-L728" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L662-L728</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L471-L548" target="_blank" rel="noreferrer">agent/src/server.js#L471-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L751-L800" target="_blank" rel="noreferrer">agent/src/server.js#L751-L800</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-preselector.js#L107-L149" target="_blank" rel="noreferrer">src/background/tool-preselector.js#L107-L149</a></li></ul>`,99)])])}const p=r(l,[["render",n]]);export{u as __pageData,p as default};
